INSERT INTO sys_re_template (template_id, case_application_id, template_name, category, content, archived, owner, create_by, create_time, update_by, update_time, design_content, description, color, cookie_name) VALUES ('8a530792-da39-4230-826f-fa768b54373e', '', '口腔初诊患者线索评估表', 'Survey', '{\n  "title": "口腔初诊患者线索评估表",\n  "description": "用于口腔门诊初诊患者意向识别、需求评估与成交跟进。",\n  "logoPosition": "right",\n  "cookieName": "dental_patient_lead_survey",\n  "pages": [\n    {\n      "name": "basicInfo",\n      "title": "基础信息",\n      "elements": [\n        {\n          "type": "text",\n          "name": "patientName",\n          "title": "您的姓名",\n          "isRequired": true\n        },\n        {\n          "type": "text",\n          "name": "patientAge",\n          "title": "您的年龄",\n          "inputType": "number",\n          "isRequired": true\n        },\n        {\n          "type": "radiogroup",\n          "name": "patientGender",\n          "title": "您的性别",\n          "isRequired": true,\n          "choices": [\n            "男",\n            "女"\n          ]\n        },\n        {\n          "type": "text",\n          "name": "phoneNumber",\n          "title": "联系电话",\n          "inputType": "tel",\n          "isRequired": true\n        },\n        {\n          "type": "text",\n          "name": "occupation",\n          "title": "您的职业"\n        },\n        {\n          "type": "text",\n          "name": "residenceArea",\n          "title": "您的居住区域"\n        },{\n          "type": "radiogroup",\n          "name": "leadSource",\n          "title": "您是通过什么渠道了解到我们的？",\n          "isRequired": true,\n          "choices": [\n            "美团",\n            "抖音",\n            "小红书",\n            "微信公众号",\n            "微信朋友圈",\n            "百度搜索",\n            "朋友介绍",\n            "社区活动",\n            "路过门店",\n            "企业微信",\n            "其他"\n          ]\n        },\n        {\n          "type": "comment",\n          "name": "leadSourceDetail",\n          "title": "如方便，请补充具体来源"\n        },{\n          "type": "checkbox",\n          "name": "dentalProblems",\n          "title": "您目前主要想解决哪些问题？",\n          "isRequired": true,\n          "choices": [\n            "牙痛",\n            "缺牙",\n            "牙齿不齐",\n            "牙齿发黄",\n            "洗牙洁牙",\n            "补牙",\n            "牙周问题",\n            "儿童牙齿问题",\n            "种植牙",\n            "牙齿矫正",\n            "牙齿美白",\n            "瓷贴面",\n            "口腔检查",\n            "其他"\n          ]\n        },\n        {\n          "type": "comment",\n          "name": "chiefComplaintDetail",\n          "title": "请简单描述您的牙齿问题或困扰",\n          "isRequired": true\n        },\n        {\n          "type": "radiogroup",\n          "name": "painLevel",\n          "title": "您当前的不适程度",\n          "choices": [\n            "无明显不适",\n            "轻微不适",\n            "中度疼痛",\n            "严重疼痛"\n          ]\n        },{\n          "type": "radiogroup",\n          "name": "treatmentTimeline",\n          "title": "您计划什么时候开始治疗？",\n          "isRequired": true,\n          "choices": [\n            "今天就希望开始",\n            "一周内",\n            "一个月内",\n            "三个月内",\n            "先了解一下"\n          ]\n        },\n        {\n          "type": "radiogroup",\n          "name": "alreadyConsulted",\n          "title": "您是否已经咨询过其他口腔机构？",\n          "choices": [\n            "是",\n            "否"\n          ]\n        },\n        {\n          "type": "radiogroup",\n          "name": "willingToTakeXray",\n          "title": "您是否愿意进行拍片检查？",\n          "choices": [\n            "愿意",\n            "暂时不确定",\n            "不愿意"\n          ]\n        },\n        {\n          "type": "radiogroup",\n          "name": "treatmentPriority",\n          "title": "您更关注哪些方面？",\n          "isRequired": true,\n          "choices": [\n            "治疗效果",\n            "医生专业度",\n            "舒适体验",\n            "材料品牌",\n            "价格性价比",\n            "治疗速度"\n          ]\n        },\n        {\n          "type": "radiogroup",\n          "name": "budgetRange",\n          "title": "您对本次治疗的大致预算范围是？",\n          "choices": [\n            "3000元以内",\n            "3000-10000元",\n            "10000-30000元",\n            "30000元以上",\n            "暂不确定"\n          ]\n        },\n        {\n          "type": "radiogroup",\n          "name": "acceptInstallment",\n          "title": "您是否接受分期付款方案？",\n          "choices": [\n            "接受",\n            "不接受",\n            "可以了解"\n          ]\n        },\n        {\n          "type": "radiogroup",\n          "name": "decisionMaker",\n          "title": "谁是本次治疗的主要决策人？",\n          "isRequired": true,\n          "choices": [\n            "本人",\n            "父母",\n            "配偶",\n            "共同决定"\n          ]\n        },{\n          "type": "radiogroup",\n          "name": "followupPreference",\n          "title": "您希望我们如何联系您？",\n          "choices": [\n            "电话",\n            "微信",\n            "短信",\n            "企业微信"\n          ]\n        },\n        {\n          "type": "dropdown",\n          "name": "visitTimePreference",\n          "title": "您方便到院的时间",\n          "choices": [\n            "工作日上午",\n            "工作日下午",\n            "工作日晚上",\n            "周末",\n            "时间待定"\n          ]\n        },\n        {\n          "type": "comment",\n          "name": "additionalNotes",\n          "title": "还有哪些需求或想了解的问题？"\n        }\n      ]\n    }\n  ]\n}', '0', '周老板', '周老板', '2025-04-30 08:23:48', '', '2025-04-30 08:48:52', '[{"id": "8ohq18", "name": "budgetConfirmed", "type": "radiogroup", "title": "Have you allocated a budget for this project?", "choices": ["Yes", "No"], "isRequired": true}, {"id": "uXi2fi", "name": "decisionMaker", "type": "text", "title": "Who is the primary decision-maker for this project?", "isRequired": true}, {"id": "cAsNIZ", "name": "businessNeed", "type": "comment", "title": "What are the key business needs or problems you are looking to solve?", "isRequired": true}, {"id": "A9gM5W", "name": "timeline", "type": "radiogroup", "title": "What is your desired purchase timeline?", "choices": ["Within 1 month", "1-3 months", "3-6 months", "6+ months"], "isRequired": true}]', 'BANT: Budget, Authority, Need, Timeline', NULL);
