INSERT INTO sys_webhook_path_index (path, tenant_id, workflow_id, node_id, workflow_name, created_at, updated_at) VALUES ('i6xzskyqmh873vmrfge5w4dr', 'tenant3', '478e33c6-ea72-4a5d-a3a7-99e7702dfb0d', 'i6xzskyqmh873vmrfge5w4dr', '478e33c6-ea72-4a5d-a3a7-99e7702dfb0d', '2026-05-28 12:28:22.34222', '2026-05-28 12:28:22.34222');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('cmjtxam2n0000w4akgebuu47p', 'EXECUTE_COMMAND', 'Execute Command', 'Execute shell commands', 'terminal', '#6366f1', '[{"name": "command", "type": "textarea", "label": "Command", "default": "", "description": "The command to execute. Use {{nodeName.propertyPath.propertyName}} for variables."}, {"name": "workingDirectory", "type": "text", "label": "Working Directory", "default": "", "description": "Optional working directory for command execution"}, {"name": "timeout", "type": "number", "label": "Timeout", "default": 30000, "description": "Command execution timeout in milliseconds (default: 30000)"}]', '2025-12-31 11:18:36.095', '2025-12-31 11:28:51.33');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('cmjty8bwl0000w4nmvxugot04', 'FORM_SUBMISSION_TRIGGER', 'On form submission', 'Create a form that collects data and triggers the workflow', 'file-text', '#8b5cf6', '[{"name": "formTitle", "type": "text", "label": "Form Title", "default": "", "description": "The title of the form"}, {"name": "formDescription", "type": "textarea", "label": "Form Description", "default": "", "description": "Description text shown on the form"}, {"name": "formElements", "type": "form-element-list", "label": "Form Elements", "default": [], "description": "Add form elements to collect data"}]', '2025-12-31 11:44:49.221', '2025-12-31 13:12:53.655');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('cmju6ljqz0000w4qv2y7mdavw', 'DO_NOTHING', 'Do Nothing', 'A placeholder node that does nothing', 'circle', '#94a3b8', '[]', '2025-12-31 15:39:02.843', '2025-12-31 15:39:02.843');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('cmjxv8yd10000w4esb6fa3qty', 'LOOP_OVER_ITEMS', 'Loop Over Items', 'Loop over items in an array from upstream node output', 'circle', '#26B99A', '[{"name": "itemsArray", "type": "text", "label": "Items Array", "default": "", "description": "Expression that resolves to an array, e.g. {{UpstreamNode.items}} or {{ $json.items }}. You can also paste a literal JSON array like [1, 2, 3].", "placeholder": "{{UpstreamNode.items}}"}, {"name": "currentItemName", "type": "text", "label": "Current Item Variable Name", "default": "item", "description": "Variable name used to expose the current loop item to nodes inside the loop branch. Defaults to \\"item\\" so you can use {{item.foo}} or {{ $json.foo }}.", "placeholder": "item"}]', '2026-01-03 05:32:24.181', '2026-04-26 11:51:06.193');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('cmjwpqcao0000w4n7cnusdbl7', 'MERGE', 'Merge', 'Merge multiple data inputs into one output', 'git-fork', '#8b5cf6', '[{"name": "mode", "type": "select", "label": "Mode", "default": "chooseBranch", "options": [{"label": "Append", "value": "append"}, {"label": "Merge Objects", "value": "merge"}, {"label": "Overwrite", "value": "overwrite"}, {"label": "Choose Branch (Last Arrived)", "value": "chooseBranch"}], "description": "How to combine data from converging branches."}]', '2026-01-02 10:10:11.521', '2026-05-26 10:19:03.968');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('cmkbzkd4p0000w4m5pk7lanb9', 'IFELSE', 'If/Else', 'Conditionally route workflow execution based on multiple conditions with AND/OR logic', '/logos/ifelse.svg', '#8b5cf6', '[{"name": "conditions", "type": "condition-list", "label": "Conditions", "default": [], "description": "Add multiple conditions. Each condition can be a boolean expression using {{variables}}."}, {"name": "combineWith", "type": "select", "label": "Combine Conditions With", "default": "AND", "options": [{"label": "AND (all conditions must be true)", "value": "AND"}, {"label": "OR (at least one condition must be true)", "value": "OR"}], "description": "How to combine multiple conditions: AND (all must be true) or OR (at least one must be true)"}]', '2026-01-13 02:42:01.466', '2026-01-13 02:45:53.866');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('cmkfa3bxe0000w40quen3zurp', 'SWITCH', 'Switch', 'Route items to multiple output branches based on routing rules. Each rule is a condition that corresponds to an output branch. Items matching a rule will be routed to that branch.', '/logos/ifelse.svg', '#8b5cf6', '[{"name": "variableName", "type": "text", "label": "Variable Name", "default": "", "description": "Variable name to store the output"}, {"name": "conditions", "type": "switch-conditions", "label": "Routing Rules", "default": [], "description": "Configure routing rules. Each rule corresponds to an output branch. Items matching a rule will be routed to that branch."}]', '2026-01-15 10:00:01.058', '2026-01-15 10:33:47.507');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('cmkglstp00000w4qacuklpr2p', 'CONVERT_TO_FILE', 'Convert to File', 'Convert data to various file formats (JSON, CSV, Text, XLSX)', 'file-down', '#6366f1', '[{"name": "operation", "type": "select", "label": "Operation", "default": "json", "options": [{"label": "Convert to JSON", "value": "json"}, {"label": "Convert to CSV", "value": "csv"}, {"label": "Convert to Text File", "value": "text"}, {"label": "Convert to XLSX", "value": "xlsx"}], "description": "The file format to convert to"}, {"name": "mode", "type": "select", "label": "Mode", "default": "allItemsToOneFile", "options": [{"label": "All Items to One File", "value": "allItemsToOneFile"}], "description": "How to handle multiple items"}, {"name": "outputField", "type": "text", "label": "Put Output File in Field", "default": "data", "description": "The field name where the converted file data will be stored"}, {"name": "encoding", "type": "select", "label": "Encoding", "default": "utf8", "options": [{"label": "ASCII", "value": "ascii"}, {"label": "Binary", "value": "binary"}, {"label": "UTF-8", "value": "utf8"}], "description": "The encoding to use for the file"}]', '2026-01-16 08:15:32.436', '2026-01-16 08:15:32.436');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('cmn6uht390000qp38x1vmoot5', 'ALIOSS', 'Aliyun OSS', 'Upload base64-encoded image data to Alibaba Cloud OSS (credentials from environment variables)', 'cloud-upload', '#FF6A00', '[{"name": "base64Template", "type": "textarea", "label": "Base64 / Data URL", "default": "", "description": "Handlebars template resolving to raw base64 or a data URL (e.g. data:image/png;base64,...). Example: {{MyNode.data}}"}, {"name": "objectKeyTemplate", "type": "text", "label": "Object key (optional)", "default": "", "description": "OSS object key template. Leave empty to auto-generate as images/<id>.<ext>"}, {"name": "contentType", "type": "text", "label": "Content-Type (fallback)", "default": "image/png", "description": "MIME type when input is raw base64 without a data: prefix. Default: image/png"}]', '2026-03-26 02:20:20.229', '2026-03-26 02:20:20.229');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('cmn6wi0r50000qpfwn2o7rgm0', 'ALIIMAGEAI', 'Ali Image AI', 'DashScope Qwen VL: understand images (URL + prompt) using Qwen credentials', 'image', '#614AFB', '[{"name": "model", "type": "text", "label": "Model", "default": "qwen3-vl-flash-2026-01-22", "description": "DashScope VL model id (e.g. qwen3-vl-flash-2026-01-22)"}, {"name": "baseUrl", "type": "text", "label": "API base URL (optional)", "default": "", "description": "OpenAI-compatible base URL; empty uses QWEN_BASE_URL or DashScope default"}, {"name": "credentialId", "type": "text", "label": "Qwen credential ID", "default": "", "description": "DashScope API key credential (same as Qwen node)"}, {"name": "imageUrlTemplate", "type": "textarea", "label": "Image URL", "default": "", "description": "Handlebars template for image URL (HTTPS or data URL), e.g. {{ALIOSS.signedUrl}}"}, {"name": "systemPrompt", "type": "textarea", "label": "System prompt (optional)", "default": "", "description": "Optional system message (Handlebars)"}, {"name": "userPrompt", "type": "textarea", "label": "User prompt", "default": "", "description": "User question about the image (Handlebars)"}, {"name": "enableThinking", "type": "boolean", "label": "Enable thinking", "default": false, "description": "Use DashScope enable_thinking via direct HTTP (required for thinking_budget)"}, {"name": "thinkingBudget", "type": "number", "label": "Thinking budget", "default": 81920, "description": "Token budget when thinking is enabled (e.g. 81920)"}]', '2026-03-26 03:16:29.393', '2026-03-26 03:16:29.393');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('n2e82spzngjlz6049rxmyms1', 'SETPROPERTY', 'Set Variables', 'Configure the properties for this node using the form below.', 'edit-3', '#f59e0b', '[{"name": "properties", "type": "key-value-list", "label": "Properties", "default": [], "description": "Add properties to set in the workflow context."}]', '2025-11-25 02:48:51.207', '2026-01-01 15:11:58.911');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('n2e82spzngjlz6049rxmyms2', 'HTTP_REQUEST', 'HTTP Request', 'HTTP Request', 'globe', '#8b5cf6', '[{"name": "endpoint", "type": "text", "label": "Request URL", "default": "https://example.com", "description": "Enter the endpoint URL."}, {"name": "method", "type": "select", "label": "Method", "default": "GET", "options": [{"label": "GET", "value": "GET"}, {"label": "POST", "value": "POST"}, {"label": "PUT", "value": "PUT"}, {"label": "PATCH", "value": "PATCH"}, {"label": "DELETE", "value": "DELETE"}]}, {"name": "headers", "type": "key-value-list", "label": "Request Headers", "default": [], "description": "Add custom headers to the request."}, {"name": "queryParams", "type": "key-value-list", "label": "Query Parameters", "default": [], "description": "Add query string parameters to the request URL."}, {"name": "body", "type": "json", "label": "Request Body", "default": {}, "description": "JSON payload to send with the request (for POST/PUT/PATCH).", "displayOptions": {"show": {"method": ["POST", "PUT", "PATCH"]}}}]', '2025-11-25 02:48:51.207', '2026-05-21 23:50:12.875');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('e6465589edfb4092b39403962d6afb3a', 'SHARED_IMPORT', 'Import to Workspace', 'Import items into the shared workflow workspace ($shared.collections).', 'database', '#0ea5e9', '[{"name": "collectionName", "type": "text", "label": "Collection Name", "default": "imported", "description": "Name of the shared collection to write items into."}, {"name": "source", "type": "select", "label": "Source", "default": "upstream", "options": [{"label": "Upstream inputs", "value": "upstream"}, {"label": "JSON template", "value": "json"}], "description": "Where to read items from."}, {"name": "itemsJson", "type": "textarea", "label": "Items JSON", "default": "[]", "description": "JSON array or template (when source is JSON).", "displayOptions": {"show": {"source": ["json"]}}}]', '2026-05-21 11:25:02.508', '2026-05-21 11:25:02.508');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('d0c5c505122a44fa9cb4b619ad16e65e', 'FILTER', 'Filter Workspace', 'Filter items in a shared collection by conditions ($json = current row).', 'filter', '#06b6d4', '[{"name": "sourceCollection", "type": "text", "label": "Source Collection", "default": "imported", "description": "Shared collection to read items from."}, {"name": "targetCollection", "type": "text", "label": "Target Collection", "default": "imported_filtered", "description": "Collection name to write filtered items into."}, {"name": "conditions", "type": "condition-list", "label": "Conditions", "default": [], "description": "Conditions per item ($json = current row)."}, {"name": "combineWith", "type": "select", "label": "Combine With", "default": "AND", "options": [{"label": "AND", "value": "AND"}, {"label": "OR", "value": "OR"}]}]', '2026-05-21 11:25:02.508', '2026-05-21 11:25:02.508');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('f6be0ee4cae14befbcacc3dd6babac58', 'REMOVE_DUPLICATES', 'Remove Duplicates', 'Remove duplicate items from upstream data by selected fields.', 'filter', '#8b5cf6', '[{"name": "arrayPath", "type": "text", "label": "Array Path", "default": "", "description": "Optional dot path to a nested array (e.g. items). Leave empty to dedupe upstream flow items."}, {"name": "compareFields", "type": "text", "label": "Fields to Compare", "default": "", "description": "Comma-separated fields on each array element. Items matching on all listed fields are duplicates; the first item is kept."}]', '2026-05-23 09:33:53.483', '2026-05-23 09:33:53.483');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('eeb2540060aa4d9cbf1ab64efb92656a', 'SPLITOUT', 'Split Out', 'Split an array field into separate items. Downstream nodes run once per element (fan-out).', 'split', '#8b5cf6', '[{"name": "fieldToSplit", "type": "text", "label": "Field to Split Out", "default": "", "description": "Dot path to array, e.g. items or data.rows"}, {"name": "keepOtherFields", "type": "boolean", "label": "Keep Other Fields", "default": false}, {"name": "failIfNotArray", "type": "boolean", "label": "Fail If Not Array", "default": false}, {"name": "destinationField", "type": "text", "label": "Destination Field", "default": "", "displayOptions": {"show": {"keepOtherFields": [true]}}}]', '2026-05-23 15:02:20.858', '2026-05-23 15:02:20.858');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('4c9fd2f954224f2b94da67b7181a5c7c', 'AGGREGATE', 'Aggregate', 'Group items and compute aggregations. Use after Split Out to summarize fan-out data.', 'aggregate', '#0ea5e9', '[{"name": "groupByFields", "type": "text", "label": "Group By Fields", "default": "", "description": "Comma-separated paths, e.g. userId. Empty = single group."}, {"name": "aggregations", "type": "aggregations", "label": "Aggregations", "default": []}]', '2026-05-23 15:02:55.999', '2026-05-23 15:02:55.999');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('2d0f2a8bf3464ed9a92b3e9b95d60fb0', 'WAIT', 'Wait', 'Pause the workflow until a duration elapses, a specific moment, or an external webhook/form callback resumes it.', 'clock', '#f59e0b', '[{"name": "mode", "type": "select", "label": "Resume On", "default": "after_time_interval", "options": [{"label": "After Time Interval", "value": "after_time_interval"}, {"label": "At Specified Time", "value": "at_specified_time"}, {"label": "On Webhook Call", "value": "on_webhook_call"}, {"label": "On Form Submitted", "value": "on_form_submitted"}], "description": "How this node resumes execution."}, {"name": "waitAmount", "type": "number", "label": "Wait Amount", "default": 5, "description": "Amount of time to wait.", "displayOptions": {"show": {"mode": ["after_time_interval"]}}}, {"name": "waitUnit", "type": "select", "label": "Wait Unit", "default": "seconds", "options": [{"label": "Seconds", "value": "seconds"}, {"label": "Minutes", "value": "minutes"}, {"label": "Hours", "value": "hours"}, {"label": "Days", "value": "days"}], "displayOptions": {"show": {"mode": ["after_time_interval"]}}}, {"name": "dateTime", "type": "datetime", "label": "Date and Time", "default": "", "description": "Absolute time to resume execution.", "displayOptions": {"show": {"mode": ["at_specified_time"]}}}, {"name": "httpMethod", "type": "select", "label": "HTTP Method", "default": "POST", "options": [{"label": "GET", "value": "GET"}, {"label": "POST", "value": "POST"}, {"label": "PUT", "value": "PUT"}, {"label": "PATCH", "value": "PATCH"}, {"label": "DELETE", "value": "DELETE"}], "displayOptions": {"show": {"mode": ["on_webhook_call"]}}}, {"name": "responseMode", "type": "select", "label": "Response Mode", "default": "onReceived", "options": [{"label": "Immediately", "value": "onReceived"}], "description": "Currently only Immediately is supported. lastNode mode is on the roadmap.", "displayOptions": {"show": {"mode": ["on_webhook_call"]}}}, {"name": "responseCode", "type": "number", "label": "Response Code", "default": 200, "displayOptions": {"show": {"mode": ["on_webhook_call"]}}}, {"name": "responseData", "type": "json", "label": "Response Data", "default": {"received": true}, "description": "JSON returned to the caller when the webhook is hit.", "displayOptions": {"show": {"mode": ["on_webhook_call"]}}}, {"name": "authentication", "type": "select", "label": "Authentication", "default": "none", "options": [{"label": "None", "value": "none"}, {"label": "Header Token", "value": "header"}, {"label": "Query Token", "value": "query"}], "displayOptions": {"show": {"mode": ["on_webhook_call"]}}}, {"name": "authTokenName", "type": "text", "label": "Token Name", "default": "x-wait-token", "description": "Header or query parameter name carrying the shared secret.", "displayOptions": {"show": {"mode": ["on_webhook_call"], "authentication": ["header", "query"]}}}, {"name": "authTokenValue", "type": "password", "label": "Token Value", "default": "", "description": "Shared secret value that callers must send.", "displayOptions": {"show": {"mode": ["on_webhook_call"], "authentication": ["header", "query"]}}}, {"name": "formTitle", "type": "text", "label": "Form Title", "default": "Please complete the form", "displayOptions": {"show": {"mode": ["on_form_submitted"]}}}, {"name": "formDescription", "type": "textarea", "label": "Form Description", "default": "", "displayOptions": {"show": {"mode": ["on_form_submitted"]}}}, {"name": "formFields", "type": "form-element-list", "label": "Form Fields", "default": [], "description": "Fields rendered for the user. Submission payload is exposed as the node output.", "displayOptions": {"show": {"mode": ["on_form_submitted"]}}}, {"name": "limitWaitTime", "type": "boolean", "label": "Limit Wait Time", "default": false, "description": "Resume automatically if the callback does not arrive in time.", "displayOptions": {"show": {"mode": ["on_webhook_call", "on_form_submitted"]}}}, {"name": "limitMode", "type": "select", "label": "Limit Mode", "default": "after_time_interval", "options": [{"label": "After Time Interval", "value": "after_time_interval"}, {"label": "At Specified Time", "value": "at_specified_time"}], "displayOptions": {"show": {"mode": ["on_webhook_call", "on_form_submitted"], "limitWaitTime": [true]}}}, {"name": "limitAmount", "type": "number", "label": "Limit Amount", "default": 1, "displayOptions": {"show": {"mode": ["on_webhook_call", "on_form_submitted"], "limitMode": ["after_time_interval"], "limitWaitTime": [true]}}}, {"name": "limitUnit", "type": "select", "label": "Limit Unit", "default": "hours", "options": [{"label": "Seconds", "value": "seconds"}, {"label": "Minutes", "value": "minutes"}, {"label": "Hours", "value": "hours"}, {"label": "Days", "value": "days"}], "displayOptions": {"show": {"mode": ["on_webhook_call", "on_form_submitted"], "limitMode": ["after_time_interval"], "limitWaitTime": [true]}}}, {"name": "limitDateTime", "type": "datetime", "label": "Limit Date and Time", "default": "", "displayOptions": {"show": {"mode": ["on_webhook_call", "on_form_submitted"], "limitMode": ["at_specified_time"], "limitWaitTime": [true]}}}]', '2026-05-25 06:40:53.899', '2026-05-25 06:40:53.899');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('3d940cf5451b4a2abc1eddc799a633d3', 'EDIT_FIELDS', 'Edit Fields', 'Transform upstream data by setting or deleting fields.', 'edit', '#14b8a6', '[{"name": "mode", "type": "select", "label": "Mode", "default": "manual", "options": [{"label": "Manual", "value": "manual"}, {"label": "JSON", "value": "json"}], "description": "Manual field mapping or edit fields as a JSON object."}, {"name": "fields", "type": "field-mapping-list", "label": "Fields", "default": [], "description": "Map fields to set or delete on upstream data.", "displayOptions": {"show": {"mode": ["manual"]}}}, {"name": "fieldsJson", "type": "json", "label": "JSON", "default": "{\\n  \\"my_field_1\\": \\"value\\",\\n  \\"my_field_2\\": 1\\n}", "description": "JSON object of fields to set on upstream data.", "displayOptions": {"show": {"mode": ["json"]}}}, {"name": "includeOtherFields", "type": "boolean", "label": "Include Other Fields", "default": true, "description": "Keep unmapped fields from the input item."}]', '2026-05-22 22:53:50.303', '2026-05-26 09:49:41.72');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('15ec3ec4d658417baa7d43a6d887efc6', 'SF_EXPRESS', 'SF Express', 'Create orders, query routes, or cancel shipments via SF Express (Fengqiao) using tenant credentials.', 'truck', '#dc2626', '[{"name": "operation", "type": "select", "label": "Operation", "default": "create_order", "options": [{"label": "Create Order", "value": "create_order"}, {"label": "Query Route", "value": "query_route"}, {"label": "Cancel Order", "value": "cancel_order"}, {"label": "Refresh Access Token", "value": "refresh_access_token"}], "description": "Which SF Express API action to perform."}, {"name": "forceRefresh", "type": "boolean", "label": "Force Refresh", "default": true, "description": "When enabled, always request a new OAuth2 accessToken from SF (2h TTL).", "displayOptions": {"show": {"operation": ["refresh_access_token"]}}}, {"name": "waybillNo", "type": "text", "label": "Waybill No", "default": "", "description": "Waybill number. Supports {{ expressions }}.", "displayOptions": {"show": {"operation": ["query_route", "cancel_order"]}}}, {"name": "orderPayload", "type": "json", "label": "Order Payload", "default": {}, "description": "Fengqiao order msgData JSON. Supports {{ expressions }} in string values.", "displayOptions": {"show": {"operation": ["create_order"]}}}, {"name": "extraParams", "type": "json", "label": "Extra Parameters", "default": {}, "description": "Optional cancel fields such as orderId when waybillNo is not used.", "displayOptions": {"show": {"operation": ["cancel_order"]}}}]', '2026-05-25 22:28:59.445', '2026-05-26 08:15:17.718');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('a1a8221bc9dc43f3944e82c7cfc2f1f5', 'CODE', 'Code', 'Run custom JavaScript or Python code on workflow data.', 'code', '#f59e0b', '[{"name": "mode", "type": "select", "label": "Mode", "default": "runOnceForAllItems", "options": [{"label": "Run Once for All Items", "value": "runOnceForAllItems"}, {"label": "Run Once for Each Item", "value": "runOnceForEachItem"}], "description": "Run code once for all input items or once per item."}, {"name": "language", "type": "select", "label": "Language", "default": "javaScript", "options": [{"label": "JavaScript", "value": "javaScript"}, {"label": "Python", "value": "python"}], "description": "Language used to execute custom code."}, {"name": "jsCode", "type": "code", "label": "JavaScript", "default": "const items = $input.all();\\nreturn items.map(item => ({\\n  json: { ...item.json, processed: true }\\n}));", "description": "JavaScript to execute. Use $input.all(), $input.first(), $input.item, $json, and context.", "displayOptions": {"show": {"language": ["javaScript"]}}}, {"name": "pythonCode", "type": "code", "label": "Python", "default": "# Python support coming soon\\nreturn _items", "description": "Python to execute (coming soon).", "displayOptions": {"show": {"language": ["python"]}}}, {"name": "pythonNotice", "type": "notice", "label": "Python", "default": "Python execution is coming soon. Only JavaScript can run in workflows today.", "displayOptions": {"show": {"language": ["python"]}}}]', '2026-05-26 11:03:12.7', '2026-05-26 11:03:12.7');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('f34d2fc38f494f798dcf235333b3062b', 'DATE_AND_TIME', 'Date & Time', 'Manipulate dates and times with common operations.', 'calendar-clock', '#6366f1', '[{"name": "operation", "type": "select", "label": "Operation", "default": "addToDate", "options": [{"label": "Add to a Date", "value": "addToDate"}, {"label": "Subtract From a Date", "value": "subtractFromDate"}, {"label": "Extract Part of a Date", "value": "extractDatePart"}, {"label": "Format a Date", "value": "formatDate"}, {"label": "Get Current Date", "value": "getCurrentDate"}, {"label": "Get Time Between Dates", "value": "getTimeBetweenDates"}, {"label": "Round a Date", "value": "roundDate"}], "description": "Date and time operation to perform."}, {"name": "date", "type": "text", "label": "Date", "default": "", "description": "Input date (ISO 8601, CRM format, or expression).", "displayOptions": {"show": {"operation": ["addToDate", "subtractFromDate", "extractDatePart", "formatDate", "roundDate"]}}}, {"name": "duration", "type": "number", "label": "Duration", "default": 1, "description": "Amount of time to add or subtract.", "displayOptions": {"show": {"operation": ["addToDate", "subtractFromDate"]}}}, {"name": "durationUnit", "type": "select", "label": "Duration Unit", "default": "days", "options": [{"label": "Seconds", "value": "seconds"}, {"label": "Minutes", "value": "minutes"}, {"label": "Hours", "value": "hours"}, {"label": "Days", "value": "days"}, {"label": "Weeks", "value": "weeks"}, {"label": "Months", "value": "months"}, {"label": "Years", "value": "years"}], "description": "Unit for the duration.", "displayOptions": {"show": {"operation": ["addToDate", "subtractFromDate"]}}}, {"name": "part", "type": "select", "label": "Part", "default": "year", "options": [{"label": "Year", "value": "year"}, {"label": "Month", "value": "month"}, {"label": "Day", "value": "day"}, {"label": "Hour", "value": "hour"}, {"label": "Minute", "value": "minute"}, {"label": "Second", "value": "second"}, {"label": "Millisecond", "value": "millisecond"}, {"label": "Day of Week", "value": "dayOfWeek"}, {"label": "Week", "value": "week"}], "description": "Part of the date to extract.", "displayOptions": {"show": {"operation": ["extractDatePart"]}}}, {"name": "format", "type": "text", "label": "Format", "default": "yyyy-MM-dd HH:mm:ss", "description": "date-fns format string (e.g. yyyy-MM-dd HH:mm:ss).", "displayOptions": {"show": {"operation": ["formatDate"]}}}, {"name": "includeTime", "type": "boolean", "label": "Include Time", "default": true, "description": "When false, returns midnight (00:00:00) for the current date.", "displayOptions": {"show": {"operation": ["getCurrentDate"]}}}, {"name": "startDate", "type": "text", "label": "Start Date", "default": "", "description": "Start date for the difference calculation.", "displayOptions": {"show": {"operation": ["getTimeBetweenDates"]}}}, {"name": "endDate", "type": "text", "label": "End Date", "default": "", "description": "End date for the difference calculation.", "displayOptions": {"show": {"operation": ["getTimeBetweenDates"]}}}, {"name": "outputUnit", "type": "select", "label": "Output Unit", "default": "days", "options": [{"label": "Milliseconds", "value": "milliseconds"}, {"label": "Seconds", "value": "seconds"}, {"label": "Minutes", "value": "minutes"}, {"label": "Hours", "value": "hours"}, {"label": "Days", "value": "days"}, {"label": "Weeks", "value": "weeks"}, {"label": "Months", "value": "months"}], "description": "Unit for the time difference result.", "displayOptions": {"show": {"operation": ["getTimeBetweenDates"]}}}, {"name": "roundTo", "type": "select", "label": "Round To", "default": "day", "options": [{"label": "Year", "value": "year"}, {"label": "Month", "value": "month"}, {"label": "Week", "value": "week"}, {"label": "Day", "value": "day"}, {"label": "Hour", "value": "hour"}, {"label": "Minute", "value": "minute"}, {"label": "Second", "value": "second"}], "description": "Granularity to round to.", "displayOptions": {"show": {"operation": ["roundDate"]}}}, {"name": "roundMode", "type": "select", "label": "Round Mode", "default": "round", "options": [{"label": "Round", "value": "round"}, {"label": "Ceil", "value": "ceil"}, {"label": "Floor", "value": "floor"}], "description": "Rounding direction.", "displayOptions": {"show": {"operation": ["roundDate"]}}}]', '2026-05-26 11:27:23.72', '2026-05-26 11:27:23.72');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('21eb758cf6ea43a3bf4cfc7a6d44018c', 'READ_WRITE_FILES', 'Read/Write Files', 'Read files from upload or URL, or write content to a downloadable file.', 'file-input', '#64748b', '[{"name": "operation", "type": "select", "label": "Operation", "default": "read", "options": [{"label": "Read File", "value": "read"}, {"label": "Write File", "value": "write"}], "description": "Read a file from upload or URL, or write content to a downloadable file."}, {"name": "readSource", "type": "select", "label": "Read Source", "default": "upload", "options": [{"label": "Uploaded File", "value": "upload"}, {"label": "URL", "value": "url"}], "description": "Where to read the file from.", "displayOptions": {"show": {"operation": ["read"]}}}, {"name": "uploadedFile", "type": "file", "label": "File", "default": null, "description": "Upload a file from your computer (stored on the server for workflow execution).", "displayOptions": {"show": {"operation": ["read"], "readSource": ["upload"]}}}, {"name": "fileUrl", "type": "text", "label": "File URL", "default": "", "description": "HTTP(S) URL to fetch (supports expressions).", "displayOptions": {"show": {"operation": ["read"], "readSource": ["url"]}}}, {"name": "outputEncoding", "type": "select", "label": "Output Encoding", "default": "auto", "options": [{"label": "Auto", "value": "auto"}, {"label": "UTF-8 Text", "value": "utf8"}, {"label": "Base64", "value": "base64"}], "description": "How to encode file content in the node output.", "displayOptions": {"show": {"operation": ["read"]}}}, {"name": "fileName", "type": "text", "label": "File Name", "default": "output.txt", "description": "Output file name including extension (supports expressions).", "displayOptions": {"show": {"operation": ["write"]}}}, {"name": "content", "type": "textarea", "label": "Content", "default": "", "description": "Text content to write (used when no upstream binary field is set).", "displayOptions": {"show": {"operation": ["write"]}}}, {"name": "inputBinaryField", "type": "text", "label": "Input Binary Field", "default": "data", "description": "Name of the binary field on upstream input (default: data). Expects base64 in binary[field].data.", "displayOptions": {"show": {"operation": ["write"]}}}, {"name": "append", "type": "boolean", "label": "Append", "default": false, "description": "Append to an existing file instead of creating a new one.", "displayOptions": {"show": {"operation": ["write"]}}}]', '2026-05-26 11:48:14.522', '2026-05-26 11:48:14.522');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('d7f40cd1e9c44feaa70ec43c674432bd', 'DOCX_TEMPLATER', 'Docx Templater', 'Generate Word documents from a remote .docx template and JSON data.', 'file-text', '#2563eb', '[{"name": "templateUrl", "type": "text", "label": "Template URL", "default": "", "description": "HTTP(S) URL of the .docx template file (supports Handlebars expressions)."}, {"name": "dataJson", "type": "textarea", "label": "Data (JSON)", "default": "{{json $json}}", "description": "JSON string passed to docxtemplater after Handlebars rendering. Must resolve to a plain object."}, {"name": "outputFilePath", "type": "text", "label": "Output File Path", "default": "document.docx", "description": "Output file name or path expression. Only the basename is used when writing to workflow storage."}, {"name": "showAdvanced", "type": "boolean", "label": "Advanced Options", "default": false, "description": "Show docxtemplater delimiter, null behavior, and image options."}, {"name": "delimiterStart", "type": "text", "label": "Delimiter Start", "default": "{", "description": "Opening delimiter for Word template placeholders.", "displayOptions": {"show": {"showAdvanced": [true]}}}, {"name": "delimiterEnd", "type": "text", "label": "Delimiter End", "default": "}", "description": "Closing delimiter for Word template placeholders.", "displayOptions": {"show": {"showAdvanced": [true]}}}, {"name": "nullGetter", "type": "select", "label": "Missing Tag Behavior", "default": "empty", "options": [{"label": "Empty string", "value": "empty"}, {"label": "Keep tag text", "value": "tag"}], "description": "Behavior when a placeholder key is missing from the data object.", "displayOptions": {"show": {"showAdvanced": [true]}}}, {"name": "defaultImageWidth", "type": "number", "label": "Max Image Width (px)", "default": 0, "description": "Maximum image width in pixels. Images wider than this are scaled down proportionally. 0 = no limit.", "displayOptions": {"show": {"showAdvanced": [true]}}}, {"name": "imageCentered", "type": "boolean", "label": "Center All Images", "default": false, "description": "Center images inserted via the image module (use {%%tag} for single centered images).", "displayOptions": {"show": {"showAdvanced": [true]}}}]', '2026-05-26 14:40:52.338', '2026-05-26 14:40:52.338');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('e02e69f76e634de2ade7b7e8b1069560', 'ALIOSS_FILE', 'Aliyun OSS (File)', 'Upload a local server file to Alibaba Cloud OSS via multipart upload.', 'cloud-upload', '#f97316', '[{"name": "filePathTemplate", "type": "text", "label": "File Path", "default": "{{docxTemplater.filePath}}", "description": "Local file path on the workflow server (supports Handlebars expressions), e.g. {{docxTemplater.filePath}}."}, {"name": "objectKeyTemplate", "type": "text", "label": "Object Key (optional)", "default": "", "description": "OSS object key (supports expressions). Leave empty to auto-generate files/<id>.<ext>."}, {"name": "contentTypeTemplate", "type": "text", "label": "Content-Type (optional)", "default": "", "description": "MIME type override (supports expressions). Leave empty to infer from file extension."}]', '2026-05-27 11:19:31.066', '2026-05-27 11:19:31.066');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('data-table-node-def-001', 'DATA_TABLE', 'Data Table', 'Insert, update, upsert, get, list, or delete rows in a Data Table', 'table', '#6366f1', '[{"name": "tableId", "type": "string", "default": "", "displayName": "Table"}, {"name": "operation", "type": "options", "default": "insert", "options": [{"name": "Insert", "value": "insert"}, {"name": "Update", "value": "update"}, {"name": "Upsert", "value": "upsert"}, {"name": "Get", "value": "get"}, {"name": "List", "value": "list"}, {"name": "Delete", "value": "delete"}], "displayName": "Operation"}, {"name": "mappingColumnMode", "type": "options", "default": "manual", "options": [{"name": "Manual", "value": "manual"}, {"name": "Automatic", "value": "automatic"}], "displayName": "Column Mapping"}, {"name": "targetField", "type": "string", "default": "", "displayName": "Target Field"}, {"name": "fields", "type": "json", "default": {}, "displayName": "Fields"}, {"name": "conditions", "type": "json", "default": [], "displayName": "Conditions"}, {"name": "combineWith", "type": "options", "default": "AND", "options": [{"name": "AND", "value": "AND"}, {"name": "OR", "value": "OR"}], "displayName": "Combine With"}, {"name": "keyFields", "type": "string", "default": "", "displayName": "Key Fields"}, {"name": "limit", "type": "number", "default": 100, "displayName": "Limit"}, {"name": "variableName", "type": "string", "default": "DataTable", "displayName": "Variable Name"}]', '2026-05-27 23:10:47.439', '2026-05-27 23:10:47.439');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('8d803926b0244215a7c9f297ce847396', 'WECOM_TAG_LIST', 'WeCom Tag List', 'Query enterprise tag library from WeChat Work via get_corp_tag_list API. Optionally filter by tag_id or group_id. If both are empty, returns all tags. Supports {{ expressions }}.', 'tag', '#07c160', '[{"name": "tag_id", "type": "text", "label": "Tag IDs", "default": "", "required": false, "description": "Comma-separated enterprise tag IDs to query. Supports {{ expressions }}. Leave empty to query by group_id or return all tags.", "placeholder": "etXXXXXXXXXX,etYYYYYYYYYY"}, {"name": "group_id", "type": "text", "label": "Group IDs", "default": "", "required": false, "description": "Comma-separated enterprise tag group IDs to query. Returns the group and all its tags. Supports {{ expressions }}. Leave empty to query by tag_id or return all tags.", "placeholder": "etZZZZZZZZZZZZZ,etYYYYYYYYYYYYY"}]', '2026-06-09 10:40:52.801', '2026-06-09 10:40:52.801');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('64179e36157446a1b023481c8ad71fdb', 'WECOM_TAG_EDITOR', 'WeCom Tag Editor', 'Add or remove enterprise tags on a customer via WeChat Work mark_tag API. Supports {{ expressions }} for userid and external_userid.', 'tag', '#07c160', '[{"name": "userid", "type": "text", "label": "Member User ID", "default": "", "required": true, "description": "The userid of the WeCom member who manages this external contact. Supports {{ expressions }}.", "placeholder": "zhangsan"}, {"name": "external_userid", "type": "text", "label": "External User ID", "default": "", "required": true, "description": "The external_userid of the customer to tag. Supports {{ expressions }}.", "placeholder": "woAJ2GCAAAd1NPGHKSD4wKmE8Aabj9AAA"}, {"name": "add_tag", "type": "text", "label": "Tags to Add", "default": "", "description": "Comma-separated enterprise tag IDs to add to the customer. Supports {{ expressions }}. Leave empty if only removing tags.", "placeholder": "TAGID1,TAGID2"}, {"name": "remove_tag", "type": "text", "label": "Tags to Remove", "default": "", "description": "Comma-separated enterprise tag IDs to remove from the customer. Supports {{ expressions }}. Leave empty if only adding tags.", "placeholder": "TAGID3,TAGID4"}]', '2026-06-09 10:12:07.022', '2026-06-09 10:12:07.022');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('webhook-trigger-node-def-001', 'WEBHOOK_TRIGGER', 'Webhook Trigger', 'Start workflow when an HTTP request hits the webhook URL', 'webhook', '#10b981', '[{"name": "variableName", "type": "string", "default": "webhookData", "displayName": "Variable Name"}, {"name": "path", "type": "string", "default": "", "displayName": "Path"}, {"name": "httpMethod", "type": "options", "default": "POST", "options": [{"name": "GET", "value": "GET"}, {"name": "POST", "value": "POST"}, {"name": "PUT", "value": "PUT"}, {"name": "PATCH", "value": "PATCH"}, {"name": "DELETE", "value": "DELETE"}], "displayName": "HTTP Method"}, {"name": "authentication", "type": "options", "default": "none", "options": [{"name": "None", "value": "none"}, {"name": "Header", "value": "header"}, {"name": "Basic", "value": "basic"}], "displayName": "Authentication"}, {"name": "headerAuthCredentialId", "type": "string", "default": "", "displayName": "Header Auth Credential"}, {"name": "authHeaderName", "type": "string", "default": "Authorization", "displayName": "Auth Header Name"}, {"name": "authHeaderValue", "type": "string", "default": "", "displayName": "Auth Header Value"}, {"name": "basicAuthUsername", "type": "string", "default": "", "displayName": "Basic Auth Username"}, {"name": "basicAuthPassword", "type": "string", "default": "", "displayName": "Basic Auth Password"}, {"name": "respond", "type": "options", "default": "immediately", "options": [{"name": "Immediately", "value": "immediately"}, {"name": "After Workflow", "value": "after_workflow"}], "displayName": "Respond"}, {"name": "respondData", "type": "options", "default": "all_entries", "options": [{"name": "All Entries", "value": "all_entries"}, {"name": "No Response Body", "value": "no_response_body"}], "displayName": "Respond Data"}]', '2026-05-28 11:50:32.748', '2026-05-28 11:50:32.748');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('369597d35b4c4feeb43f7598cbc39b48', 'AI_AGENT', 'AI Agent', 'Run CRM tools with ReAct or Planner reasoning.', 'bot', '#8b5cf6', '[{"name": "provider", "type": "select", "label": "Provider", "default": "", "options": [{"label": "Qwen (DashScope)", "value": "qwen"}, {"label": "DeepSeek", "value": "deepseek"}, {"label": "OpenAI", "value": "openai"}, {"label": "Gemini", "value": "gemini"}, {"label": "Anthropic", "value": "anthropic"}], "description": "Optional. Leave empty with no credential to use default Gemini via server environment key."}, {"name": "model", "type": "text", "label": "Model", "default": "", "description": "Model id for the selected provider."}, {"name": "credentialId", "type": "text", "label": "Credential", "default": "", "description": "API credential matching the selected provider."}, {"name": "baseUrl", "type": "text", "label": "API Base URL", "default": "", "description": "Optional override for OpenAI-compatible providers."}, {"name": "mode", "type": "select", "label": "Mode", "default": "react", "options": [{"label": "ReAct", "value": "react"}, {"label": "Planner", "value": "planner"}], "description": "ReAct uses a tool loop; Planner generates a plan then executes steps."}, {"name": "userPrompt", "type": "textarea", "label": "User Prompt", "default": "", "description": "Task for the agent. Supports {{ NodeName.field }} expressions."}, {"name": "systemPrompt", "type": "textarea", "label": "System Prompt", "default": "", "description": "Optional extra system instructions appended to the default CRM assistant prompt."}, {"name": "stepLimit", "type": "number", "label": "Step Limit", "default": 8, "description": "Maximum tool-calling steps (1-8)."}, {"name": "enabledTools", "type": "json", "label": "Enabled Tools", "default": [], "description": "Tool name whitelist. Empty array enables all registered CRM tools."}]', '2026-05-21 14:45:19.675', '2026-05-28 23:44:59.888');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('589c4708a5eb4f76ae180bfe5271240b', 'MCP_CLIENT', 'MCP Client', 'Execute a tool on an external Model Context Protocol server.', 'plug', '#0d9488', '[{"name": "connectionMode", "type": "select", "label": "Connection", "default": "saved", "options": [{"label": "Saved MCP server", "value": "saved"}, {"label": "Inline endpoint", "value": "inline"}]}, {"name": "mcpServerId", "type": "number", "label": "MCP Server", "default": "", "description": "Saved server from Integrations."}, {"name": "url", "type": "text", "label": "MCP Endpoint URL", "default": "", "description": "HTTPS MCP endpoint (inline mode)."}, {"name": "transport", "type": "select", "label": "Server Transport", "default": "http", "options": [{"label": "HTTP Streamable", "value": "http"}, {"label": "SSE (legacy)", "value": "sse"}]}, {"name": "authentication", "type": "select", "label": "Authentication", "default": "none", "options": [{"label": "None", "value": "none"}, {"label": "Header Auth", "value": "header"}, {"label": "Basic Auth", "value": "basic"}]}, {"name": "headerAuthCredentialId", "type": "string", "label": "Header Auth Credential", "default": "", "description": "HEADER_AUTH credential ID from w_credentials (inline mode)."}, {"name": "authHeaderName", "type": "string", "label": "Header Name", "default": "Authorization"}, {"name": "authHeaderValue", "type": "string", "label": "Header Value", "default": ""}, {"name": "basicAuthUsername", "type": "string", "label": "Basic Auth Username", "default": ""}, {"name": "basicAuthPassword", "type": "string", "label": "Basic Auth Password", "default": ""}, {"name": "toolName", "type": "text", "label": "Tool", "default": "", "description": "MCP tool name to execute."}, {"name": "inputMode", "type": "select", "label": "Input mode", "default": "json", "options": [{"label": "Manual", "value": "manual"}, {"label": "JSON", "value": "json"}]}, {"name": "toolInputJson", "type": "json", "label": "Tool input (JSON)", "default": {}, "description": "Arguments object for the selected tool."}, {"name": "toolParameters", "type": "key-value-list", "label": "Tool parameters", "default": [], "description": "Key-value tool arguments (manual mode)."}, {"name": "timeoutMs", "type": "number", "label": "Timeout (ms)", "default": 60000, "description": "Maximum time to wait for the tool call."}]', '2026-06-01 11:22:19.731', '2026-06-01 11:22:19.731');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('e71bf1aa535f47e2901915d0950e7cb2', 'CRM_RECORD_TRIGGER', 'CRM Record Trigger', 'Start the workflow when a CRM record is created, updated, or deleted', 'database', '#0ea5e9', '[{"name": "entityType", "type": "select", "label": "Object", "default": "lead", "options": [{"label": "Lead", "value": "lead"}, {"label": "Contact", "value": "contact"}, {"label": "Company", "value": "organization"}, {"label": "Opportunity", "value": "opportunity"}]}, {"name": "eventType", "type": "select", "label": "Event", "default": "created", "options": [{"label": "Record is Created", "value": "created"}, {"label": "Record is Updated", "value": "updated"}, {"label": "Record is Updated or Created", "value": "upsert"}, {"label": "Record is Deleted", "value": "deleted"}]}]', '2026-06-01 13:05:26.657', '2026-06-01 13:05:26.657');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('3d589df4ecb44ecf956ce94a23305c57', 'WHILE', 'While', 'Repeat a loop branch while conditions are true.', 'repeat', '#6366f1', '[{"name": "conditions", "type": "condition-list", "label": "Conditions", "default": [], "description": "Define conditions to evaluate for looping."}, {"name": "combineWith", "type": "select", "label": "Combine With", "default": "AND", "options": [{"label": "AND", "value": "AND"}, {"label": "OR", "value": "OR"}], "description": "How to combine multiple conditions."}, {"name": "maxIterations", "type": "number", "label": "Max Iterations", "default": 100, "description": "Safety cap to prevent infinite loops."}]', '2026-06-02 11:48:31.368', '2026-06-02 11:48:31.368');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('1ff13468e05246adb812b98665fa169e', 'LLM', 'LLM', 'Generate text with Qwen, Gemini, DeepSeek, OpenAI, or Anthropic.', 'sparkles', '#6366f1', '[{"name": "provider", "type": "select", "label": "Provider", "default": "qwen", "options": [{"label": "Qwen (DashScope)", "value": "qwen"}, {"label": "DeepSeek", "value": "deepseek"}, {"label": "OpenAI", "value": "openai"}, {"label": "Gemini", "value": "gemini"}, {"label": "Anthropic", "value": "anthropic"}], "description": "LLM provider to call."}, {"name": "model", "type": "select", "label": "Model", "default": "qwen-plus", "description": "Model id for the selected provider."}, {"name": "credentialId", "type": "text", "label": "Credential", "default": "", "description": "API credential matching the selected provider."}, {"name": "baseUrl", "type": "text", "label": "API Base URL", "default": "", "description": "Optional override for OpenAI-compatible providers."}, {"name": "systemPrompt", "type": "textarea", "label": "System Prompt", "default": "", "description": "Optional system instructions. Supports {{ NodeName.field }} expressions."}, {"name": "userPrompt", "type": "textarea", "label": "User Prompt", "default": "", "description": "Required user message template. Supports {{ NodeName.field }} expressions."}, {"name": "outputMode", "type": "select", "label": "Output Mode", "default": "text", "options": [{"label": "Text", "value": "text"}, {"label": "Structured JSON", "value": "structured"}], "description": "Text returns plain text; structured returns a typed JSON object."}, {"name": "outputSchema", "type": "select", "label": "Output Schema Preset", "default": "searchQueries", "options": [{"label": "Search Queries", "value": "searchQueries"}, {"label": "Sufficiency Analysis", "value": "sufficientAnalysis"}], "description": "Built-in schema preset for structured output.", "displayOptions": {"show": {"outputMode": ["structured"]}}}]', '2026-06-02 11:49:22.864', '2026-06-02 11:49:22.864');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('fe3960a367ec449b883fbf31f07e8dea', 'WECOM_KF', 'WeChat KF', 'Send messages, manage KF accounts, servicers, and query customer info via WeChat Customer Service API.', 'message-circle', '#07c160', '[{"name": "operation", "type": "select", "label": "Operation", "default": "send_msg", "options": [{"label": "Send Message", "value": "send_msg"}, {"label": "Add KF Account", "value": "add_kf_account"}, {"label": "Delete KF Account", "value": "del_kf_account"}, {"label": "Update KF Account", "value": "update_kf_account"}, {"label": "List KF Accounts", "value": "list_kf_account"}, {"label": "Get KF Account Link", "value": "get_kf_account_link"}, {"label": "Add Servicer", "value": "add_servicer"}, {"label": "Delete Servicer", "value": "del_servicer"}, {"label": "List Servicers", "value": "list_servicer"}, {"label": "Get Customer Info", "value": "get_customer_info"}], "description": "WeChat KF API operation to perform."}, {"name": "accessToken", "type": "text", "label": "Access Token (Advanced)", "default": "", "description": "Optional. Auto-obtained via CRM backend if left empty.", "displayOptions": {"advanced": true}}, {"name": "touser", "type": "text", "label": "External User ID", "default": "", "description": "The external_userid of the customer. Supports {{ expressions }}.", "displayOptions": {"show": {"operation": ["send_msg"]}}}, {"name": "openKfid", "type": "text", "label": "KF Account ID (open_kfid)", "default": "", "description": "The open_kfid of the customer service account.", "displayOptions": {"show": {"operation": ["send_msg", "del_kf_account", "update_kf_account", "get_kf_account_link", "add_servicer", "del_servicer", "list_servicer"]}}}, {"name": "msgtype", "type": "select", "label": "Message Type", "default": "text", "options": [{"label": "Text", "value": "text"}, {"label": "Image", "value": "image"}, {"label": "Voice", "value": "voice"}, {"label": "Video", "value": "video"}, {"label": "File", "value": "file"}], "description": "Type of message to send.", "displayOptions": {"show": {"operation": ["send_msg"]}}}, {"name": "textContent", "type": "textarea", "label": "Text Content", "default": "", "description": "Text message content. Supports {{ expressions }}.", "displayOptions": {"show": {"operation": ["send_msg"]}}}, {"name": "storeToDatabase", "type": "boolean", "label": "Store to Database", "default": false, "description": "When enabled, the sent message will be persisted to crm_wecom_kf_message (direction=2).", "displayOptions": {"show": {"operation": ["send_msg"]}}}, {"name": "name", "type": "text", "label": "Account Name", "default": "", "description": "Display name for the KF account.", "displayOptions": {"show": {"operation": ["add_kf_account", "update_kf_account"]}}}, {"name": "mediaId", "type": "text", "label": "Media ID", "default": "", "description": "Optional. Avatar media_id for the KF account.", "displayOptions": {"show": {"operation": ["add_kf_account", "update_kf_account"]}}}, {"name": "useridList", "type": "text", "label": "User ID List", "default": "", "description": "Comma-separated user IDs of the servicers.", "displayOptions": {"show": {"operation": ["add_servicer", "del_servicer"]}}}, {"name": "externalUserid", "type": "text", "label": "External User ID", "default": "", "description": "The external_userid of the customer to query. Supports {{ expressions }}.", "displayOptions": {"show": {"operation": ["get_customer_info"]}}}]', '2026-06-05 10:39:00.387', '2026-06-05 10:39:00.387');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('1db54f7c30d84ca883fbf4535997fead', 'WECOM_UP_MEDIA', 'WeCom Upload Media', 'Upload a file to WeChat Work as temporary media and get a media_id for use in subsequent nodes.', 'upload', '#07c160', '[{"name": "fileUrl", "type": "text", "label": "File URL", "default": "", "required": true, "description": "URL or path to the file to upload. Supports {{ expressions }}. Can be a file from a previous node output.", "placeholder": "https://example.com/file.png or {{ prevNode.fileUrl }}"}, {"name": "mediaType", "type": "select", "label": "Media Type", "default": "image", "options": [{"label": "Image", "value": "image"}, {"label": "Voice", "value": "voice"}, {"label": "Video", "value": "video"}, {"label": "File", "value": "file"}], "required": true, "description": "WeChat Work media type. Affects file size limits and how the media can be used."}]', '2026-06-07 22:56:54.701', '2026-06-07 22:56:54.701');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('716fb25045294dac9756c074ee0ae826', 'WECOM_GP_MSG', 'WeCom Group Message', 'Create an enterprise group message template for sending to customers or customer groups via WeChat Work.', 'send', '#07c160', '[{"name": "chatType", "type": "select", "label": "Message Type", "default": "single", "options": [{"label": "Send to Customers", "value": "single"}, {"label": "Send to Customer Groups", "value": "group"}], "required": true, "description": "Whether to send the message to individual customers or customer groups."}, {"name": "sender", "type": "text", "label": "Sender ID", "default": "", "description": "User ID of the member sending the message. Required when sending to customer groups. Supports {{ expressions }}."}, {"name": "externalUserid", "type": "text", "label": "External User IDs", "default": "", "description": "Comma-separated list of external user IDs, or a JSON array. Only valid for single chat type. Supports {{ expressions }}."}, {"name": "chatIdList", "type": "text", "label": "Chat Group IDs", "default": "", "description": "Comma-separated list of customer group chat IDs, or a JSON array. Only valid for group chat type. Supports {{ expressions }}."}, {"name": "tagFilterJson", "type": "json", "label": "Tag Filter", "default": "", "description": "JSON object with group_list for tag-based filtering."}, {"name": "allowSelect", "type": "boolean", "label": "Allow Re-select", "default": false, "description": "Whether the sending member can re-select recipients from the pending list."}, {"name": "textContent", "type": "text", "label": "Message Text", "default": "", "description": "Text content of the message, up to 4000 bytes."}, {"name": "attachmentsJson", "type": "json", "label": "Attachments", "default": "", "description": "JSON array of attachment objects (image, link, miniprogram, video, file)."}]', '2026-06-08 00:02:51.756', '2026-06-08 00:02:51.756');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('c5e0aea6e9bf46d8894799a84014fc32', 'WECOM_UP_IMG', 'WeCom Upload Image', 'Upload an image to WeChat Work and get a permanent URL for use in rich-text messages and welcome messages.', 'image', '#07c160', '[{"name": "fileUrl", "type": "text", "label": "File URL", "default": "", "required": true, "description": "URL or path to the image file to upload. Supports {{ expressions }}. Can be a file from a previous node output.", "placeholder": "https://example.com/image.png or {{ prevNode.fileUrl }}"}]', '2026-06-09 07:32:33.2', '2026-06-09 07:32:33.2');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('b23c9b57d020489f901a4ae2fdd8611f', 'WECOM_UP_ATTACHMENT', 'WeCom Upload Attachment', 'Upload a file to WeChat Work as an attachment and get a temporary media_id (valid 3 days) for use in Moments or Product Album scenarios.', 'paperclip', '#07c160', '[{"name": "fileUrl", "type": "text", "label": "File URL", "default": "", "required": true, "description": "URL or path to the file to upload. Supports {{ expressions }}. Can be a file from a previous node output.", "placeholder": "https://example.com/file.png or {{ prevNode.fileUrl }}"}, {"name": "mediaType", "type": "select", "label": "Media Type", "default": "image", "options": [{"label": "Image", "value": "image"}, {"label": "Video", "value": "video"}, {"label": "File", "value": "file"}], "required": true, "description": "WeChat Work media type. Affects which attachment_type values are valid."}, {"name": "attachmentType", "type": "select", "label": "Attachment Type", "default": "1", "options": [{"label": "Moments (朋友圈)", "value": "1"}, {"label": "Product Album (商品图册)", "value": "2"}], "required": true, "description": "Attachment scenario type. 1 = Moments (image/video only). 2 = Product Album (image only)."}]', '2026-06-09 07:43:46.463', '2026-06-09 07:43:46.463');
INSERT INTO w_node_definition (id, type, label, description, icon, color, parameters, created_at, updated_at) VALUES ('d35125ffaa0a44d89730d828d0fc993e', 'WECOM_SEND_MOMENT', 'WeCom Send Moment', 'Publish content to customer Moments (朋友圈) via WeChat Work API. Supports text, images, video, and link attachments with configurable visible range.', 'send', '#07c160', '[{"name": "textContent", "type": "textarea", "label": "Text Content", "default": "", "description": "Text content of the Moment post. Supports {{ expressions }}. Up to 2000 characters. Either text or attachments must be provided.", "placeholder": "Enter Moment text content..."}, {"name": "attachmentsJson", "type": "json", "label": "Attachments", "default": "", "description": "JSON array of attachment objects. Each must have msgtype and corresponding fields (image.media_id, video.media_id, or link.url + link.media_id). Max 9 images, or 1 video, or 1 link."}, {"name": "userList", "type": "text", "label": "Sender User IDs", "default": "", "description": "Comma-separated user IDs of members who will publish the Moment. Supports {{ expressions }}. Leave empty to publish for all members in visible range.", "placeholder": "zhangsan,lisi"}, {"name": "departmentList", "type": "text", "label": "Sender Department IDs", "default": "", "description": "Comma-separated department IDs whose members will publish the Moment. Supports {{ expressions }}.", "placeholder": "2,3"}, {"name": "tagList", "type": "text", "label": "Target Customer Tags", "default": "", "description": "Comma-separated customer tag IDs. Only customers with these tags will see the Moment. Supports {{ expressions }}. Leave empty for all customers.", "placeholder": "etXXXXXXXXXX,etYYYYYYYYYY"}]', '2026-06-09 08:11:24.176', '2026-06-09 08:11:24.176');
